\begin{lemma}[Linear-time normal equation]
\label{lem:normal}Let there exist $v_{i}\in V(T)$ for each $i\in\{1,\ldots,m\}$
such that
\begin{equation}
A_{i,j}\ne0\qquad\implies\qquad j=v_{i}\text{ or }j=p(v_{i}).\label{eq:Asparsity}
\end{equation}
Define $\H$ and $\q$ according to (\ref{eq:Hqdef}). Then, under
Assumption~\ref{ass:lin}:
\begin{enumerate}
\item (Forming) It costs $O(\omega^{6}n)$ time and $O(\omega^{4}n)$ space
to form $\H$ and $\q$, where $\omega=\max_{j}|J_{j}|=1+\wid(\T)$.
\item (Factoring) Let $\pi$ be a topological ordering on $T$, and define
the associated block topological permutation $\Pi$ as in Lemma~\ref{lem:blocktree}.
Then, it costs $O(\omega^{6}n)$ time and $O(\omega^{4}n)$ space
to factor $\Pi\H\Pi^{T}$ into $\L\L^{T}$. 
\item (Solving) Given $r$, $\q$, $\Pi$, and the Cholesky factor $\L$
satisfying $\L\L^{T}=\Pi\H\Pi^{T}$, it costs $O(\omega^{4}n)$ time
and space to solve $(\H+\q\q^{T})u=r$ for $u$.
\end{enumerate}
\end{lemma}

\begin{lemma}
\label{lem:row-rank}The matrix $\N$ in (\ref{eq:Nmat}) has full
row rank, that is $\det(\N\N^{T})\ne0$.
\end{lemma}

\begin{lemma}[Orthogonal complement]
\label{lem:orth}Let $d=\frac{1}{2}\sum_{j=1}^{\ell}|J_{j}|(|J_{j}|+1)$.
Implicitly define the $d\times\frac{1}{2}n(n+1)$ matrix $\P$ to
satisfy
\begin{align*}
\P\,\vector(X) & =[\vector(X[J_{1},J_{1}]);\ldots;\vector(X[J_{\ell},J_{\ell}])]\qquad\forall X\in\S^{n}.
\end{align*}
Then, (i) $\N\P=0$; (ii) every $x\in\R^{d}$ can be decomposed as
$x=\N^{T}u+\P v$. 
\end{lemma}

\begin{proof}
For each $x=[\vector(X_{j})]_{j=1}^{\ell}\in\R^{d}$, Theorem~\ref{thm:ctree}
says that there exists a $Z$ satisfying $\P\,\vector(Z)=x$ if and
only if $\N x=0$. Equivalently, $x\in\mathrm{span}(\P)$ if and only
if $x\perp\mathrm{span}(\N^{T})$. The ``only if'' part implies
(i), while the ``if'' part implies (ii).
\end{proof}

\begin{proof}[Lemma~\ref{lem:slaterp}]We will prove that 
\[
\text{exists }x\in\Int(\K),\quad\begin{bmatrix}\A\\
\N
\end{bmatrix}x=\begin{bmatrix}b\\
0
\end{bmatrix}\qquad\iff\qquad\text{exists }X\succeq0,\quad\M\,\vector(X)=b.
\]
Define the chordal completion $F$ as in (\ref{eq:chordal_compl}).
Observe that $\M\,\vector(X)=\M\,\vector(Z)$ holds for all pairs
of $P_{F}(X)=Z$, because each $A_{i}\in\S_{F}^{n}$ satisfies $A_{i}\bullet X=A_{i}\bullet P_{F}(X)$.
Additionally, the positive definite version of Theorem~\ref{thm:prim_sep}
is written
\begin{gather}
\text{exists }X\succ0,\quad P_{F}(X)=Z\qquad\iff\qquad\P\,\vector(Z)\in\Int(\K).\label{eq:prim_sep}
\end{gather}
This result was first established by Grone et al.~\cite{grone1984positive};
a succinct proof can be found in~\cite[Theorem~10.1]{vandenberghe2015chordal}.\textbf{
($\implies$)} For every $x$ satisfying $\N x=0$, there exists $Z$
such that $\P\,\vector(Z)=x$ due to Lemma~\ref{lem:orth}. If additionally
$x\in\Int(\K)$, then there exists $X\succ0$ satisfying $Z=P_{F}(X)$
due to (\ref{eq:prim_sep}). We can verify that $\M\,\vector(X)=\M\,\vector(Z)=\A\P\,\vector(Z)=\A x=b$.\textbf{
($\impliedby$)} For every $X\succ0,$ there exists $Z$ satisfying
$Z=P_{F}(X)$ and $\P\,\vector(Z)\in\Int(\K)$ due to (\ref{eq:prim_sep}).
Set $u=\P\,\vector(Z)$ and observe that $u\in\Int(\K)$ and $\N u=\N\P\,\vector(Z)=0$.
If additionally $\M\,\vector(X)=b$, then $\A u=\A\P\,\vector(Z)=\M\,\vector(Z)=b$.\qed \end{proof}

\begin{lemma}[$\epsilon$-accurate and $\epsilon$-feasible]
\label{lem:eps}If $(x,y,s,\tau,\theta,\kappa)$ satisfies (\ref{eq:hsdfeas})
and (\ref{eq:hsdcone}) and 
\begin{align*}
\mu=\frac{x^{T}s+\tau\kappa}{\nu+1} & \le\epsilon, & \tau\kappa\ge & \gamma\mu
\end{align*}
for constants $\epsilon,\gamma>0$, then the rescaled point $(x/\tau,y/\tau,s/\tau)$
satisfies
\begin{align*}
\|\M(x/\tau)-\b\| & \le K\epsilon, & \|\M^{T}(y/\tau)+(s/\tau)-\c\| & \le K\epsilon, & \frac{(x/\tau)^{T}(s/\tau)}{\nu+1}\le K\epsilon
\end{align*}
where $K$ is a constant.
\end{lemma}

